use rustycad_tkernel::ncollection::DynamicArray;
use std::marker::PhantomPinned;
fn require_send_sync<T: Send + Sync>() {}
fn require_unpin<T: Unpin>() {}
fn require_unwind<T: std::panic::UnwindSafe + std::panic::RefUnwindSafe>() {}
fn covariance<'short, 'long: 'short>(value: DynamicArray<&'long i32>) -> DynamicArray<&'short i32> { value }
fn main() {
    require_send_sync::<DynamicArray<i32>>();
    require_unpin::<DynamicArray<PhantomPinned>>();
    require_unwind::<DynamicArray<i32>>();
